  @visibleForTesting
  Future<void> waitingCaptureLostJobsForTest() => _waiting.captureLostJobs();

  /// Test seam: the current restart-honesty count.
  @visibleForTesting
  int get waitingLostJobsForTest => _waiting.lostJobs;

