      script = _settleScript;
    } else if (_leadScripts.isNotEmpty) {
      script = _leadScripts.removeAt(0);
    } else {
      script = textTurn('noted.');
    }
    final stream = AssistantMessageEventStream();
    for (final event in script) {
      stream.push(event);
    }
    stream.end();
