String waitingDetachSummary(WaiterSnapshot snap) {
  final jobs = snap.jobs.length;
  final timers = snap.timers.length;
  return '$jobs background job${jobs == 1 ? '' : 's'} detached '
      '(logs: .fah/bash_jobs/) · '
