/// advances when [releaseNextSleep] lets a drain sleep complete, so the
/// test observes every steer deterministically.
class _LivenessHarness {
  _LivenessHarness._({
    required this.cli,
    required this.io,
    required this.stream,
    required this.shell,
    required this.env,
    required this.run,
    required this._clockOf,
