  /// path gets the same bookkeeping (issue #1152 round-1).
  Future<void> _sendUserMessage(
    String text,
    List<TuiImageAttachment> images,
  ) async {
    if (_viewer != null) {
      await _viewerSend(text);
      return;
    }
    _approval.clearTurnGrants();
    _startRun(text, images: images);
