        stream.contexts[i],
  ];

  /// The call-time user text of the n-th liveness run (1-based).
  String livenessNotice(int n) {
    var seen = 0;
    for (var i = 0; i < stream.contexts.length; i++) {
      if (!stream.continuations[i] &&
