    test('a sealed append never throws and returns without writing', ...);
    test('compaction records are their own writer class', ...);
  });

  group('UT-5 resume after seal', () {
    test('a sealed session reopened by a new Session appends normally', ...);
    test('seal is idempotent and the first sink wins', ...);
  });
